package com.rafat.munasabati;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.view.*;import android.widget.*;

public class TemplateChooserActivity extends Activity{
    private static final String P="munasabati_templates";private int primary,accent=Color.rgb(208,151,56);private LinearLayout root;private GridLayout grid;
    private boolean ar(){return AppSettings.isArabic(this);}private String tr(String a,String e){return AppSettings.tr(this,a,e);}private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}private GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
    @Override public void onCreate(Bundle b){super.onCreate(b);V4Theme.apply(this);primary=V4Theme.primary(this);getWindow().setStatusBarColor(primary);ScrollView s=new ScrollView(this);s.setFillViewport(true);s.setBackgroundColor(ModernUi.screenBackground(this));root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(14),dp(12),dp(14),dp(28));root.setLayoutDirection(ar()?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);s.addView(root);LinearLayout hero=new LinearLayout(this);hero.setOrientation(LinearLayout.VERTICAL);hero.setPadding(dp(17),dp(15),dp(17),dp(17));hero.setBackground(bg(primary,26));hero.setElevation(dp(5));root.addView(hero,new LinearLayout.LayoutParams(-1,-2));TextView h=t(tr("ابدأ بقالب ذكي","Start with a smart template"),26,true);h.setTextColor(Color.WHITE);hero.addView(h);TextView sub=t(tr("اختصر الوقت ثم عدّل ما تحتاجه فقط","Save time, then customize only what you need"),13,false);sub.setTextColor(Color.rgb(222,239,236));hero.addView(sub);Button quick=new Button(this);quick.setAllCaps(false);quick.setText(tr("＋ إضافة سريعة فارغة","＋ Quick blank event"));quick.setTextColor(primary);quick.setBackground(bg(Color.WHITE,14));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(-1,dp(48));qp.setMargins(0,dp(12),0,0);hero.addView(quick,qp);quick.setOnClickListener(v->open("none","none","30",tr("مناسبة جديدة","New event"),false));String lastCat=getSharedPreferences(P,0).getString("cat","");if(!lastCat.isEmpty()){TextView recent=t(tr("استخدمته مؤخرًا","Recently used"),16,true);recent.setTextColor(ModernUi.ink(this));recent.setPadding(0,dp(16),0,dp(6));root.addView(recent);Button r=new Button(this);r.setAllCaps(false);String ln=getSharedPreferences(P,0).getString("name",Categories.label(this,lastCat));r.setText("↻  "+ln);r.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);r.setTextColor(primary);r.setBackground(bg(ModernUi.surface(this),17));root.addView(r,new LinearLayout.LayoutParams(-1,dp(54)));r.setOnClickListener(v->open(lastCat,getSharedPreferences(P,0).getString("rec","none"),getSharedPreferences(P,0).getString("rem","30"),ln,true));}TextView section=t(tr("اختر نوع المناسبة","Choose event type"),18,true);section.setTextColor(ModernUi.ink(this));section.setPadding(dp(2),dp(18),dp(2),dp(9));root.addView(section);grid=new GridLayout(this);grid.setColumnCount(2);root.addView(grid,new LinearLayout.LayoutParams(-1,-2));add("＋",tr("مناسبة فارغة","Blank event"),tr("ابدأ من الصفر","Start from scratch"),"none","none","30");add("🎂",tr("عيد ميلاد","Birthday"),tr("سنوي • أسبوع + يوم","Yearly • week + day"),"birthday","yearly","10080,1440");add("💍",tr("زواج","Wedding"),tr("تنبيهات قبل الموعد","Helpful reminders"),"marriage","none","1440,180");add("✈",tr("سفر","Travel"),tr("يوم + 3 ساعات","Day + 3 hours"),"travel","none","1440,180");add("💼",tr("اجتماع","Meeting"),tr("ساعة + 15 دقيقة","Hour + 15 min"),"meeting","none","60,15");add("🌙",tr("عشاء","Dinner"),tr("تنبيهات اجتماعية","Social reminders"),"dinner","none","180,60");add("🩺",tr("موعد طبي","Medical appointment"),tr("يوم + ساعة","Day + hour"),"medical","none","1440,60");setContentView(s);}
    private void add(String icon,String name,String subtitle,String cat,String rec,String rem){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setGravity(Gravity.CENTER_HORIZONTAL);card.setPadding(dp(13),dp(13),dp(13),dp(12));card.setBackground(bg(ModernUi.surface(this),22));card.setElevation(dp(2));card.setClickable(true);TextView i=t(icon,28,false);i.setGravity(Gravity.CENTER);i.setBackground(bg(Color.rgb(255,248,229),17));i.setTextColor(accent);card.addView(i,new LinearLayout.LayoutParams(dp(58),dp(58)));TextView n=t(name,15,true);n.setTextColor(ModernUi.ink(this));n.setGravity(Gravity.CENTER);n.setPadding(0,dp(9),0,0);card.addView(n);TextView d=t(subtitle,11,false);d.setTextColor(ModernUi.muted(this));d.setGravity(Gravity.CENTER);d.setMaxLines(2);card.addView(d);GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.height=dp(145);p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.setMargins(dp(4),dp(4),dp(4),dp(4));grid.addView(card,p);card.setOnClickListener(v->open(cat,rec,rem,name,true));}
    private void open(String cat,String rec,String rem,String name,boolean remember){if(remember&&!"none".equals(cat))getSharedPreferences(P,0).edit().putString("cat",cat).putString("rec",rec).putString("rem",rem).putString("name",name).apply();Intent i=new Intent(this,EditEventActivity.class).putExtra("template_category",cat).putExtra("template_recurrence",rec).putExtra("template_reminders",rem).putExtra("template_name",name);startActivity(i);finish();}
    private TextView t(String x,int s,boolean bold){TextView v=new TextView(this);v.setText(x);v.setTextSize(s);if(bold)v.setTypeface(null,1);return v;}
}
